        auto const ch1 = *p++;
        if (UNLIKELY(ch1 != '0')) return false;
        auto const ch2 = *p++;
        if (UNLIKELY(ch2 != '0')) return false;
        auto const dch3 = dehexchar(*p++);
        if (UNLIKELY(dch3 < 0)) return false;
        auto const dch4 = dehexchar(*p++);
        if (UNLIKELY(dch4 < 0)) return false;
        out = (dch3 << 4) | dch4;
        return true;
      } else {
        uint16_t u16cp = 0;
        for (int i = 0; i < 4; i++) {
          auto const hexv = dehexchar(*p++);
          if (hexv < 0) return false; // includes check for end of string
          u16cp <<= 4;
          u16cp |= hexv;
        }
        if (u16cp > 0x7f) {
          return false;
        } else {
          out = u16cp;
          return true;
        }
      }
    }
    default: return false;
  }
}

bool VariableUnserializer::matchString(folly::StringPiece str) {
  const char* p = m_buf;
  assertx(p <= m_end);
  int total = 0;
  if (*p == 'S' && type() == VariableUnserializer::Type::APCSerialize) {
    total = 2 + 8 + 1;
    if (p + total > m_end) return false;
    p++;
    if (*p++ != ':') return false;
    auto const sd = *reinterpret_cast<StringData*const*>(p);
    assertx(sd->isStatic());
    if (str.compare(sd->slice()) != 0) return false;
    p += size_t(8);
  } else {
    const auto ss = str.size();
    if (ss >= 100) return false;
    int digits = ss >= 10 ? 2 : 1;
    total = 2 + digits + 2 + ss + 2;
    if (p + total > m_end) return false;
    if (*p++ != 's') return false;
    if (*p++ != ':') return false;
    if (digits == 2) {
      if (*p++ != '0' + ss/10) return false;
      if (*p++ != '0' + ss%10) return false;
    } else {
      if (*p++ != '0' + ss) return false;
    }
    if (*p++ != ':') return false;
    if (*p++ != '\"') return false;
    if (memcmp(p, str.data(), ss)) return false;
    p += ss;
    if (*p++ != '\"') return false;
  }
  if (*p++ != ';') return false;
  assertx(m_buf + total == p);
  m_buf = p;
  return true;
}

