      tmp1 = data.binary.salt[0];
      tmp2 = data.binary.salt[1];
      tmp3 = data.binary.salt[2];
      tmp4 = data.binary.salt[3];
      for (i = 0; i < BF_N; i += 4) {
        data.ctx.P[i] ^= tmp1;
        data.ctx.P[i + 1] ^= tmp2;
        data.ctx.P[i + 2] ^= tmp3;
        data.ctx.P[i + 3] ^= tmp4;
      }
      data.ctx.P[16] ^= tmp1;
      data.ctx.P[17] ^= tmp2;
    } while (1);
  } while (--count);

  for (i = 0; i < 6; i += 2) {
    L = BF_magic_w[i];
    R = BF_magic_w[i + 1];

    count = 64;
