  memcpy(output, setting, 7 + 22 - 1);
  output[7 + 22 - 1] = BF_itoa64[(int)
    BF_atoi64[(int)setting[7 + 22 - 1] - 0x20] & 0x30];

/* This has to be bug-compatible with the original implementation, so
