int bad_format(
    char *fmt)
{
    char     *ptr;
    int       n = 0;

    ptr = fmt;
    while (*ptr != '\0')
        if (*ptr++ == '%') {

            /* line cannot end with percent char */
            if (*ptr == '\0')
                return 1;
            /* '%s', '%S' and '%%' are allowed */
            if (*ptr == 's' || *ptr == 'S' || *ptr == '%')
                ptr++;
            /* %c is allowed (but use only with vdef!) */
            else if (*ptr == 'c') {
                ptr++;
                n = 1;
            }

            /* or else '% 6.2lf' and such are allowed */
            else {
                /* optional padding character */
                if (*ptr == ' ' || *ptr == '+' || *ptr == '-')
                    ptr++;
                /* This should take care of 'm.n' with all three optional */
                while (*ptr >= '0' && *ptr <= '9')
                    ptr++;
                if (*ptr == '.')
                    ptr++;
                while (*ptr >= '0' && *ptr <= '9')
                    ptr++;
                /* Either 'le', 'lf' or 'lg' must follow here */
                if (*ptr++ != 'l')
                    return 1;
                if (*ptr == 'e' || *ptr == 'f' || *ptr == 'g')
                    ptr++;
                else
                    return 1;
                n++;
            }
        }

    return (n != 1);
}

int bad_format_imginfo(
    char *fmt)
{
    char     *ptr;
    int       n = 0;

    ptr = fmt;
    while (*ptr != '\0')
        if (*ptr++ == '%') {

            /* line cannot end with percent char */
            if (*ptr == '\0')
                return 1;
            /* '%%' is allowed */
            if (*ptr == '%')
                ptr++;
            /* '%s', '%S' are allowed */
            else if (*ptr == 's' || *ptr == 'S') {
                n = 1;
                ptr++;
            }

            /* or else '% 4lu' and such are allowed */
            else {
                /* optional padding character */
                if (*ptr == ' ')
                    ptr++;
                /* This should take care of 'm' */
                while (*ptr >= '0' && *ptr <= '9')
                    ptr++;
                /* 'lu' must follow here */
                if (*ptr++ != 'l')
                    return 1;
                if (*ptr == 'u')
                    ptr++;
                else
                    return 1;
                n++;
            }
        }

    return (n != 3);
}

void rrd_graph_options(
    int argc,
    char *argv[],
    image_desc_t
    *im)
{
    int       stroff;
    char     *parsetime_error = NULL;
    char      scan_gtm[12], scan_mtm[12], scan_ltm[12], col_nam[12];
    char      double_str[20], double_str2[20];
    time_t    start_tmp = 0, end_tmp = 0;
    long      long_tmp;
    rrd_time_value_t start_tv, end_tv;
    long unsigned int color;

    /* defines for long options without a short equivalent. should be bytes,
       and may not collide with (the ASCII value of) short options */
#define LONGOPT_UNITS_SI 255

/* *INDENT-OFF* */
    struct option long_options[] = {
        { "alt-autoscale",      no_argument,       0, 'A'},
        { "imgformat",          required_argument, 0, 'a'},
        { "font-smoothing-threshold", required_argument, 0, 'B'},
        { "base",               required_argument, 0, 'b'},
        { "color",              required_argument, 0, 'c'},
        { "full-size-mode",     no_argument,       0, 'D'},
        { "daemon",             required_argument, 0, 'd'},
        { "slope-mode",         no_argument,       0, 'E'},
        { "end",                required_argument, 0, 'e'},
        { "force-rules-legend", no_argument,       0, 'F'},
        { "imginfo",            required_argument, 0, 'f'},
        { "graph-render-mode",  required_argument, 0, 'G'},
        { "no-legend",          no_argument,       0, 'g'},
        { "height",             required_argument, 0, 'h'},
        { "no-minor",           no_argument,       0, 'I'},
        { "interlaced",         no_argument,       0, 'i'},
        { "alt-autoscale-min",  no_argument,       0, 'J'},
        { "only-graph",         no_argument,       0, 'j'},
        { "units-length",       required_argument, 0, 'L'},
        { "lower-limit",        required_argument, 0, 'l'},
        { "alt-autoscale-max",  no_argument,       0, 'M'},
        { "zoom",               required_argument, 0, 'm'},
        { "no-gridfit",         no_argument,       0, 'N'},
        { "font",               required_argument, 0, 'n'},
        { "logarithmic",        no_argument,       0, 'o'},
        { "pango-markup",       no_argument,       0, 'P'},
        { "font-render-mode",   required_argument, 0, 'R'},
        { "rigid",              no_argument,       0, 'r'},
        { "step",               required_argument, 0, 'S'},
        { "start",              required_argument, 0, 's'},
        { "tabwidth",           required_argument, 0, 'T'},
        { "title",              required_argument, 0, 't'},
        { "upper-limit",        required_argument, 0, 'u'},
        { "vertical-label",     required_argument, 0, 'v'},
        { "watermark",          required_argument, 0, 'W'},
        { "width",              required_argument, 0, 'w'},
        { "units-exponent",     required_argument, 0, 'X'},
        { "x-grid",             required_argument, 0, 'x'},
        { "alt-y-grid",         no_argument,       0, 'Y'},
        { "y-grid",             required_argument, 0, 'y'},
        { "lazy",               no_argument,       0, 'z'},
        { "use-nan-for-all-missing-data", no_argument,       0, 'Z'},
        { "units",              required_argument, 0, LONGOPT_UNITS_SI},
        { "alt-y-mrtg",         no_argument,       0, 1000},    /* this has no effect it is just here to save old apps from crashing when they use it */
        { "disable-rrdtool-tag",no_argument,       0, 1001},
        { "right-axis",         required_argument, 0, 1002},
        { "right-axis-label",   required_argument, 0, 1003},
        { "right-axis-format",  required_argument, 0, 1004},
        { "legend-position",    required_argument, 0, 1005},
        { "legend-direction",   required_argument, 0, 1006},
        { "border",             required_argument, 0, 1007},
        { "grid-dash",          required_argument, 0, 1008},
        { "dynamic-labels",     no_argument,       0, 1009},
        { "week-fmt",           required_argument, 0, 1010},
        { "graph-type",         required_argument, 0, 1011},
        { "left-axis-format",   required_argument, 0, 1012},
        {  0, 0, 0, 0}
};
/* *INDENT-ON* */

    optind = 0;
    opterr = 0;         /* initialize getopt */
    rrd_parsetime("end-24h", &start_tv);
    rrd_parsetime("now", &end_tv);
    while (1) {
        int       option_index = 0;
        int       opt;
        int       col_start, col_end;

        opt = getopt_long(argc, argv,
                          "Aa:B:b:c:Dd:Ee:Ff:G:gh:IiJjL:l:Mm:Nn:oPR:rS:s:T:t:u:v:W:w:X:x:Yy:Zz",
                          long_options, &option_index);
        if (opt == EOF)
            break;
        switch (opt) {
        case 'I':
            im->extra_flags |= NOMINOR;
            break;
        case 'Y':
            im->extra_flags |= ALTYGRID;
            break;
        case 'A':
            im->extra_flags |= ALTAUTOSCALE;
            break;
        case 'J':
            im->extra_flags |= ALTAUTOSCALE_MIN;
            break;
        case 'M':
            im->extra_flags |= ALTAUTOSCALE_MAX;
            break;
        case 'j':
            im->extra_flags |= ONLY_GRAPH;
            break;
        case 'g':
            im->extra_flags |= NOLEGEND;
            break;
        case 'Z':
            im->extra_flags |= ALLOW_MISSING_DS;
            break;
        case 1005:
            if (strcmp(optarg, "north") == 0) {
                im->legendposition = NORTH;
            } else if (strcmp(optarg, "west") == 0) {
                im->legendposition = WEST;
            } else if (strcmp(optarg, "south") == 0) {
                im->legendposition = SOUTH;
            } else if (strcmp(optarg, "east") == 0) {
                im->legendposition = EAST;
            } else {
                rrd_set_error("unknown legend-position '%s'", optarg);
                return;
            }
            break;
        case 1006:
            if (strcmp(optarg, "topdown") == 0) {
                im->legenddirection = TOP_DOWN;
            } else if (strcmp(optarg, "bottomup") == 0) {
                im->legenddirection = BOTTOM_UP;
            } else if (strcmp(optarg, "bottomup2") == 0) {
                im->legenddirection = BOTTOM_UP2;
            } else {
                rrd_set_error("unknown legend-position '%s'", optarg);
                return;
            }
            break;
        case 'F':
            im->extra_flags |= FORCE_RULES_LEGEND;
            break;
        case 1001:
            im->extra_flags |= NO_RRDTOOL_TAG;
            break;
        case LONGOPT_UNITS_SI:
            if (im->extra_flags & FORCE_UNITS) {
                rrd_set_error("--units can only be used once!");
                return;
            }
            if (strcmp(optarg, "si") == 0)
                im->extra_flags |= FORCE_UNITS_SI;
            else {
                rrd_set_error("invalid argument for --units: %s", optarg);
                return;
            }
            break;
        case 'X':
            im->unitsexponent = atoi(optarg);
            break;
        case 'L':
            im->unitslength = atoi(optarg);
            im->forceleftspace = 1;
            break;
        case 'T':
            if (rrd_strtodbl(optarg, 0, &(im->tabwidth), "option -T") != 2)
                return;
            break;
        case 'S':
            im->step = atoi(optarg);
            break;
        case 'N':
            im->gridfit = 0;
            break;
        case 'P':
            im->with_markup = 1;
            break;
        case 's':
            if ((parsetime_error = rrd_parsetime(optarg, &start_tv))) {
                rrd_set_error("start time: %s", parsetime_error);
                return;
            }
            break;
        case 'e':
            if ((parsetime_error = rrd_parsetime(optarg, &end_tv))) {
                rrd_set_error("end time: %s", parsetime_error);
                return;
            }
            break;
        case 'x':
            if (strcmp(optarg, "none") == 0) {
                im->draw_x_grid = 0;
                break;
            };
            if (sscanf(optarg,
                       "%10[A-Z]:%ld:%10[A-Z]:%ld:%10[A-Z]:%ld:%ld:%n",
                       scan_gtm,
                       &im->xlab_user.gridst,
                       scan_mtm,
                       &im->xlab_user.mgridst,
                       scan_ltm,
                       &im->xlab_user.labst,
                       &im->xlab_user.precis, &stroff) == 7 && stroff != 0) {
				im->xlab_form=strdup(optarg + stroff);
				if (!im->xlab_form) {
                    rrd_set_error("cannot allocate memory for xlab_form");
                    return;
				}
                if ((int)
                    (im->xlab_user.gridtm = tmt_conv(scan_gtm)) == -1) {
                    rrd_set_error("unknown keyword %s", scan_gtm);
                    return;
                } else if ((int)
                           (im->xlab_user.mgridtm = tmt_conv(scan_mtm))
                           == -1) {
                    rrd_set_error("unknown keyword %s", scan_mtm);
                    return;
                } else if ((int)
                           (im->xlab_user.labtm = tmt_conv(scan_ltm)) == -1) {
                    rrd_set_error("unknown keyword %s", scan_ltm);
                    return;
                }
                im->xlab_user.minsec = 1;
                im->xlab_user.stst = im->xlab_form ? im->xlab_form : "";
            } else {
                rrd_set_error("invalid x-grid format");
                return;
            }
            break;
        case 'y':
            if (strcmp(optarg, "none") == 0) {
                im->draw_y_grid = 0;
                break;
            };
            if (sscanf(optarg, "%[-0-9.e+]:%d", double_str , &im->ylabfact) == 2) {
                if (rrd_strtodbl( double_str, 0, &(im->ygridstep), "option -y") != 2){
                    return;
                }
                if (im->ygridstep <= 0) {
                    rrd_set_error("grid step must be > 0");
                    return;
                } else if (im->ylabfact < 1) {
                    rrd_set_error("label factor must be > 0");
                    return;
                }
            } else {
                rrd_set_error("invalid y-grid format");
                return;
            }
            break;
        case 1007:
            im->draw_3d_border = atoi(optarg);
            break;
        case 1008: /* grid-dash */
            if(sscanf(optarg,
                      "%[-0-9.e+]:%[-0-9.e+]",
                      double_str,
                      double_str2 ) != 2) {
                if ( rrd_strtodbl( double_str, 0, &(im->grid_dash_on),NULL) !=2 
                     || rrd_strtodbl( double_str2, 0, &(im->grid_dash_off), NULL) != 2 ){
                    rrd_set_error("expected grid-dash format float:float");
                    return;
                }
            }
            break;   
        case 1009: /* enable dynamic labels */
            im->dynamic_labels = 1;
            break;         
        case 1010:
            strncpy(week_fmt,optarg,sizeof week_fmt);
            week_fmt[(sizeof week_fmt)-1]='\0';
            break;
        case 1002: /* right y axis */
            if(sscanf(optarg,
                      "%[-0-9.e+]:%[-0-9.e+]",
                      double_str,
                      double_str2 ) == 2
                && rrd_strtodbl( double_str, 0, &(im->second_axis_scale),NULL) == 2
                && rrd_strtodbl( double_str2, 0, &(im->second_axis_shift),NULL) == 2){
                if(im->second_axis_scale==0){
                    rrd_set_error("the second_axis_scale  must not be 0");
                    return;
                }
            } else {
                rrd_set_error("invalid right-axis format expected scale:shift");
                return;
            }
            break;
        case 1003:
            im->second_axis_legend=strdup(optarg);
            if (!im->second_axis_legend) {
                rrd_set_error("cannot allocate memory for second_axis_legend");
                return;
            }
            break;
        case 1004:
            if (bad_format(optarg)){
                rrd_set_error("use either %le or %lf formats");
                return;
            }
            im->second_axis_format=strdup(optarg);
            if (!im->second_axis_format) {
                rrd_set_error("cannot allocate memory for second_axis_format");
                return;
            }
            break;
        case 1012:
            if (bad_format(optarg)){
                rrd_set_error("use either %le or %lf formats");
                return;
            }
            im->primary_axis_format=strdup(optarg);
            if (!im->primary_axis_format) {
                rrd_set_error("cannot allocate memory for primary_axis_format");
                return;
            }
            break;
        case 'v':
            im->ylegend=strdup(optarg);
            if (!im->ylegend) {
                rrd_set_error("cannot allocate memory for ylegend");
                return;
            }
            break;
        case 'u':
            if (rrd_strtodbl(optarg, 0, &(im->maxval), "option -u") != 2){
                return;
            }
            break;
        case 'l':
            if (rrd_strtodbl(optarg, 0, &(im->minval), "option -l") != 2){
                return;
            }
            break;
        case 'b':
            im->base = atol(optarg);
            if (im->base != 1024 && im->base != 1000) {
                rrd_set_error
                    ("the only sensible value for base apart from 1000 is 1024");
                return;
            }
            break;
        case 'w':
            long_tmp = atol(optarg);
            if (long_tmp < 10) {
                rrd_set_error("width below 10 pixels");
                return;
            }
            im->xsize = long_tmp;
            break;
        case 'h':
            long_tmp = atol(optarg);
            if (long_tmp < 10) {
                rrd_set_error("height below 10 pixels");
                return;
            }
            im->ysize = long_tmp;
            break;
        case 'D':
            im->extra_flags |= FULL_SIZE_MODE;
            break;
        case 'i':
            /* interlaced png not supported at the moment */
            break;
        case 'r':
            im->rigid = 1;
            break;
        case 'f':
            im->imginfo = optarg;
            break;
        case 'a':
            if ((int)
                (im->imgformat = if_conv(optarg)) == -1) {
                rrd_set_error("unsupported graphics format '%s'", optarg);
                return;
            }
            break;
        case 1011:
            if ((int)
                (im->graph_type = type_conv(optarg)) == -1) {
                rrd_set_error("unsupported graphics type '%s'", optarg);
                return;
            }
            break;
        case 'z':
            im->lazy = 1;
            break;
        case 'E':
            im->slopemode = 1;
            break;
        case 'o':
            im->logarithmic = 1;
            break;
        case 'c':
            if (sscanf(optarg,
                       "%10[A-Z]#%n%8lx%n",
                       col_nam, &col_start, &color, &col_end) == 2) {
                int       ci;
                int       col_len = col_end - col_start;

                switch (col_len) {
                case 3:
                    color =
                        (((color & 0xF00) * 0x110000) | ((color & 0x0F0) *
                                                         0x011000) |
                         ((color & 0x00F)
                          * 0x001100)
                         | 0x000000FF);
                    break;
                case 4:
                    color =
                        (((color & 0xF000) *
                          0x11000) | ((color & 0x0F00) *
                                      0x01100) | ((color &
                                                   0x00F0) *
                                                  0x00110) |
                         ((color & 0x000F) * 0x00011)
                        );
                    break;
                case 6:
                    color = (color << 8) + 0xff /* shift left by 8 */ ;
                    break;
                case 8:
                    break;
                default:
                    rrd_set_error("the color format is #RRGGBB[AA]");
                    return;
                }
                if ((ci = grc_conv(col_nam)) != -1) {
                    im->graph_col[ci] = gfx_hex_to_col(color);
                } else {
                    rrd_set_error("invalid color name '%s'", col_nam);
                    return;
                }
            } else {
                rrd_set_error("invalid color def format");
                return;
            }
            break;
        case 'n':{
            char      prop[15];
            double    size = 1;
            int       end;

            if (sscanf(optarg, "%10[A-Z]:%[-0-9.e+]%n", prop, double_str, &end) >= 2
                && rrd_strtodbl( double_str, 0, &size, NULL) == 2) {
                int       sindex, propidx;

                if ((sindex = text_prop_conv(prop)) != -1) {
                    for (propidx = sindex;
                         propidx < TEXT_PROP_LAST; propidx++) {
                        if (size > 0) {
                            rrd_set_font_desc(im,propidx,NULL,size);
                        }
                        if ((int) strlen(optarg) > end+2) {
                            if (optarg[end] == ':') {
                                rrd_set_font_desc(im,propidx,optarg + end + 1,0);
                            } else {
                                rrd_set_error
                                    ("expected : after font size in '%s'",
                                     optarg);
                                return;
                            }
                        }
                        /* only run the for loop for DEFAULT (0) for
                           all others, we break here. woodo programming */
                        if (propidx == sindex && sindex != 0)
                            break;
                    }
                } else {
                    rrd_set_error("invalid fonttag '%s'", prop);
                    return;
                }
            } else {
                rrd_set_error("invalid text property format");
                return;
            }
            break;
        }
        case 'm':
            if (rrd_strtodbl(optarg, 0, &(im->zoom), "option -m") != 2){
                return;
            }
            if (im->zoom <= 0.0) {
                rrd_set_error("zoom factor must be > 0");
                return;
            }
            break;
        case 't':
            im->title=strdup(optarg);
            if (!im->title) {
                rrd_set_error("cannot allocate memory for title");
                return;
            }
            break;
        case 'R':
            if (strcmp(optarg, "normal") == 0) {
                cairo_font_options_set_antialias
                    (im->font_options, CAIRO_ANTIALIAS_GRAY);
                cairo_font_options_set_hint_style
                    (im->font_options, CAIRO_HINT_STYLE_FULL);
            } else if (strcmp(optarg, "light") == 0) {
                cairo_font_options_set_antialias
                    (im->font_options, CAIRO_ANTIALIAS_GRAY);
                cairo_font_options_set_hint_style
                    (im->font_options, CAIRO_HINT_STYLE_SLIGHT);
            } else if (strcmp(optarg, "mono") == 0) {
                cairo_font_options_set_antialias
                    (im->font_options, CAIRO_ANTIALIAS_NONE);
                cairo_font_options_set_hint_style
                    (im->font_options, CAIRO_HINT_STYLE_FULL);
            } else {
                rrd_set_error("unknown font-render-mode '%s'", optarg);
                return;
            }
            break;
        case 'G':
            if (strcmp(optarg, "normal") == 0)
                im->graph_antialias = CAIRO_ANTIALIAS_GRAY;
            else if (strcmp(optarg, "mono") == 0)
                im->graph_antialias = CAIRO_ANTIALIAS_NONE;
            else {
                rrd_set_error("unknown graph-render-mode '%s'", optarg);
                return;
            }
            break;
        case 'B':
            /* not supported curently */
            break;
        case 'W':
            im->watermark=strdup(optarg);
            if (!im->watermark) {
                rrd_set_error("cannot allocate memory for watermark");
                return;
            }
            break;
        case 'd':
        {
            if (im->daemon_addr != NULL)
            {
                rrd_set_error ("You cannot specify --daemon "
                        "more than once.");
                return;
            }

            im->daemon_addr = strdup(optarg);
            if (im->daemon_addr == NULL)
            {
              rrd_set_error("strdup failed");
              return;
            }

            break;
        }
        case '?':
            if (optopt != 0)
                rrd_set_error("unknown option '%c'", optopt);
            else
                rrd_set_error("unknown option '%s'", argv[optind - 1]);
            return;
        }
    } /* while (1) */

    pango_cairo_context_set_font_options(pango_layout_get_context(im->layout), im->font_options);
    pango_layout_context_changed(im->layout);



    if (im->logarithmic && im->minval <= 0) {
        rrd_set_error
            ("for a logarithmic yaxis you must specify a lower-limit > 0");
        return;
    }

    if (rrd_proc_start_end(&start_tv, &end_tv, &start_tmp, &end_tmp) == -1) {
        /* error string is set in rrd_parsetime.c */
        return;
    }

    if (start_tmp < 3600 * 24 * 365 * 10) {
        rrd_set_error
            ("the first entry to fetch should be after 1980 (%ld)",
             start_tmp);
        return;
    }

    if (end_tmp < start_tmp) {
        rrd_set_error
            ("start (%ld) should be less than end (%ld)", start_tmp, end_tmp);
        return;
    }

    im->start = start_tmp;
    im->end = end_tmp;
    im->step = max((long) im->step, (im->end - im->start) / im->xsize);
}

rrd_info_t *rrd_graph_v(
    int argc,
    char **argv)
{
    image_desc_t im;
    rrd_info_t *grinfo;
    rrd_graph_init(&im);
    /* a dummy surface so that we can measure text sizes for placements */
    rrd_graph_options(argc, argv, &im);
    if (rrd_test_error()) {
        rrd_info_free(im.grinfo);
        im_free(&im);
        return NULL;
    }

    if (optind >= argc) {
        rrd_info_free(im.grinfo);
        im_free(&im);
        rrd_set_error("missing filename");
        return NULL;
    }

    if (strlen(argv[optind]) >= MAXPATH) {
        rrd_set_error("filename (including path) too long");
        rrd_info_free(im.grinfo);
        im_free(&im);
        return NULL;
    }

    strncpy(im.graphfile, argv[optind], MAXPATH - 1);
    im.graphfile[MAXPATH - 1] = '\0';

    if (strcmp(im.graphfile, "-") == 0) {
        im.graphfile[0] = '\0';
    }

    rrd_graph_script(argc, argv, &im, 1);

    if (rrd_test_error()) {
        rrd_info_free(im.grinfo);
        im_free(&im);
        return NULL;
    }

    /* Everything is now read and the actual work can start */
    if (graph_paint(&im) == -1) {
      rrd_info_free(im.grinfo);
      im_free(&im);
      return NULL;
    }

    /* The image is generated and needs to be output.
     ** Also, if needed, print a line with information about the image.
     */

    if (im.imginfo && *im.imginfo) {
        rrd_infoval_t info;
        char     *path;
        char     *filename;

        if (bad_format_imginfo(im.imginfo)) {
            rrd_info_free(im.grinfo);
            im_free(&im);
            rrd_set_error("bad format for imginfo");
            return NULL;
        }
        path = strdup(im.graphfile);
        filename = basename(path);
        info.u_str =
            sprintf_alloc(im.imginfo,
                          filename,
                          (long) (im.zoom *
                                  im.ximg), (long) (im.zoom * im.yimg));
        grinfo_push(&im, sprintf_alloc("image_info"), RD_I_STR, info);
        free(info.u_str);
        free(path);
    }
    if (im.rendered_image) {
        rrd_infoval_t img;

        img.u_blo.size = im.rendered_image_size;
        img.u_blo.ptr = im.rendered_image;
        grinfo_push(&im, sprintf_alloc("image"), RD_I_BLO, img);
    }
    grinfo = im.grinfo;
    im_free(&im);
    return grinfo;
}

int print_calc(
    image_desc_t *im)
{
    long      i, ii, validsteps;
    double    printval;
    struct tm tmvdef;
    int       graphelement = 0;
    long      vidx;
    int       max_ii;
    double    magfact = -1;
    char     *si_symb = "";
    char     *percent_s;
    int       prline_cnt = 0;

    /* wow initializing tmvdef is quite a task :-) */
    time_t    now = time(NULL);

    localtime_r(&now, &tmvdef);
    for (i = 0; i < im->gdes_c; i++) {
        vidx = im->gdes[i].vidx;
        switch (im->gdes[i].gf) {
        case GF_PRINT:
        case GF_GPRINT:
            /* PRINT and GPRINT can now print VDEF generated values.
             * There's no need to do any calculations on them as these
             * calculations were already made.
             */
            if (im->gdes[vidx].gf == GF_VDEF) { /* simply use vals */
                printval = im->gdes[vidx].vf.val;
                localtime_r(&im->gdes[vidx].vf.when, &tmvdef);
            } else {    /* need to calculate max,min,avg etcetera */
                max_ii = ((im->gdes[vidx].end - im->gdes[vidx].start)
                          / im->gdes[vidx].step * im->gdes[vidx].ds_cnt);
                printval = DNAN;
                validsteps = 0;
                for (ii = im->gdes[vidx].ds;
                     ii < max_ii; ii += im->gdes[vidx].ds_cnt) {
                    if (!finite(im->gdes[vidx].data[ii]))
                        continue;
                    if (isnan(printval)) {
                        printval = im->gdes[vidx].data[ii];
                        validsteps++;
                        continue;
                    }

                    switch (im->gdes[i].cf) {
                    case CF_HWPREDICT:
                    case CF_MHWPREDICT:
                    case CF_DEVPREDICT:
                    case CF_DEVSEASONAL:
                    case CF_SEASONAL:
                    case CF_AVERAGE:
                        validsteps++;
                        printval += im->gdes[vidx].data[ii];
                        break;
                    case CF_MINIMUM:
                        printval = min(printval, im->gdes[vidx].data[ii]);
                        break;
                    case CF_FAILURES:
                    case CF_MAXIMUM:
                        printval = max(printval, im->gdes[vidx].data[ii]);
                        break;
                    case CF_LAST:
                        printval = im->gdes[vidx].data[ii];
                    }
                }
                if (im->gdes[i].cf == CF_AVERAGE || im->gdes[i].cf > CF_LAST) {
                    if (validsteps > 1) {
                        printval = (printval / validsteps);
                    }
                }
            }           /* prepare printval */

            if (!im->gdes[i].strftm && (percent_s = strstr(im->gdes[i].format, "%S")) != NULL) {
                /* Magfact is set to -1 upon entry to print_calc.  If it
                 * is still less than 0, then we need to run auto_scale.
                 * Otherwise, put the value into the correct units.  If
                 * the value is 0, then do not set the symbol or magnification
                 * so next the calculation will be performed again. */
                if (magfact < 0.0) {
                    auto_scale(im, &printval, &si_symb, &magfact);
                    if (printval == 0.0)
                        magfact = -1.0;
                } else {
                    printval /= magfact;
                }
                *(++percent_s) = 's';
            } else if (!im->gdes[i].strftm && strstr(im->gdes[i].format, "%s") != NULL) {
                auto_scale(im, &printval, &si_symb, &magfact);
            }

            if (im->gdes[i].gf == GF_PRINT) {
                rrd_infoval_t prline;

                if (im->gdes[i].strftm) {
                    prline.u_str = (char*)malloc((FMT_LEG_LEN + 2) * sizeof(char));
                    if (im->gdes[vidx].vf.never == 1) {
                       time_clean(prline.u_str, im->gdes[i].format);
                    } else {
                        strftime(prline.u_str,
                                 FMT_LEG_LEN, im->gdes[i].format, &tmvdef);
                    }
                } else if (bad_format(im->gdes[i].format)) {
                    rrd_set_error
                        ("bad format for PRINT in '%s'", im->gdes[i].format);
                    return -1;
                } else {
                    prline.u_str =
                        sprintf_alloc(im->gdes[i].format, printval, si_symb);
                }
                grinfo_push(im,
                            sprintf_alloc
                            ("print[%ld]", prline_cnt++), RD_I_STR, prline);
                free(prline.u_str);
            } else {
                /* GF_GPRINT */

                if (im->gdes[i].strftm) {
                    if (im->gdes[vidx].vf.never == 1) {
                       time_clean(im->gdes[i].legend, im->gdes[i].format);
                    } else {
                        strftime(im->gdes[i].legend,
                                 FMT_LEG_LEN, im->gdes[i].format, &tmvdef);
                    }
                } else {
                    if (bad_format(im->gdes[i].format)) {
                        rrd_set_error
                            ("bad format for GPRINT in '%s'",
                             im->gdes[i].format);
                        return -1;
                    }
                    snprintf(im->gdes[i].legend,
                             FMT_LEG_LEN - 2,
                             im->gdes[i].format, printval, si_symb);
                }
                graphelement = 1;
            }
            break;
        case GF_LINE:
        case GF_AREA:
		case GF_GRAD:
        case GF_TICK:
            graphelement = 1;
            break;
        case GF_HRULE:
            if (isnan(im->gdes[i].yrule)) { /* we must set this here or the legend printer can not decide to print the legend */
                im->gdes[i].yrule = im->gdes[vidx].vf.val;
            };
            graphelement = 1;
            break;
        case GF_VRULE:
            if (im->gdes[i].xrule == 0) {   /* again ... the legend printer needs it */
                im->gdes[i].xrule = im->gdes[vidx].vf.when;
            };
            graphelement = 1;
            break;
        case GF_COMMENT:
        case GF_TEXTALIGN:
        case GF_DEF:
        case GF_CDEF:
        case GF_VDEF:
#ifdef WITH_PIECHART
        case GF_PART:
#endif
        case GF_SHIFT:
        case GF_XPORT:
            break;
        case GF_STACK:
            rrd_set_error
                ("STACK should already be turned into LINE or AREA here");
            return -1;
            break;
        case GF_XAXIS:
        case GF_YAXIS:
	    break;
        }
    }
    return graphelement;
}

int bad_format_axis(char *fmt){
    return bad_format_check("^" SAFE_STRING FLOAT_STRING SAFE_STRING "$",fmt);
}

static int bad_format_check(const char *pattern, char *fmt) {
    GError *gerr = NULL;
    GRegex *re = g_regex_new(pattern, G_REGEX_EXTENDED, 0, &gerr);
    GMatchInfo *mi;
    if (gerr != NULL) {
        rrd_set_error("cannot compile regular expression: %s (%s)", gerr->message,pattern);
        return 1;
    }
    int m = g_regex_match(re, fmt, 0, &mi);
    g_match_info_free (mi);
    g_regex_unref(re);
    if (!m) {
        rrd_set_error("invalid format string '%s' (should match '%s')",fmt,pattern);
        return 1;
    }
    return 0;
}

int bad_format_imginfo(char *fmt){
    return bad_format_check("^" SAFE_STRING "%s" SAFE_STRING "%lu" SAFE_STRING "%lu" SAFE_STRING "$",fmt);
}

int bad_format_print(char *fmt){
    return bad_format_check("^" SAFE_STRING FLOAT_STRING SAFE_STRING "%s" SAFE_STRING "$",fmt);
}

void rrd_graph_options(
    int argc,
    char *argv[],
    image_desc_t
    *im)
{
    int       stroff;
    char     *parsetime_error = NULL;
    char      scan_gtm[12], scan_mtm[12], scan_ltm[12], col_nam[12];
    char      double_str[20], double_str2[20];
    time_t    start_tmp = 0, end_tmp = 0;
    long      long_tmp;
    rrd_time_value_t start_tv, end_tv;
    long unsigned int color;

    /* defines for long options without a short equivalent. should be bytes,
       and may not collide with (the ASCII value of) short options */
#define LONGOPT_UNITS_SI 255

/* *INDENT-OFF* */
    struct option long_options[] = {
        { "alt-autoscale",      no_argument,       0, 'A'},
        { "imgformat",          required_argument, 0, 'a'},
        { "font-smoothing-threshold", required_argument, 0, 'B'},
        { "base",               required_argument, 0, 'b'},
        { "color",              required_argument, 0, 'c'},
        { "full-size-mode",     no_argument,       0, 'D'},
        { "daemon",             required_argument, 0, 'd'},
        { "slope-mode",         no_argument,       0, 'E'},
        { "end",                required_argument, 0, 'e'},
        { "force-rules-legend", no_argument,       0, 'F'},
        { "imginfo",            required_argument, 0, 'f'},
        { "graph-render-mode",  required_argument, 0, 'G'},
        { "no-legend",          no_argument,       0, 'g'},
        { "height",             required_argument, 0, 'h'},
        { "no-minor",           no_argument,       0, 'I'},
        { "interlaced",         no_argument,       0, 'i'},
        { "alt-autoscale-min",  no_argument,       0, 'J'},
        { "only-graph",         no_argument,       0, 'j'},
        { "units-length",       required_argument, 0, 'L'},
        { "lower-limit",        required_argument, 0, 'l'},
        { "alt-autoscale-max",  no_argument,       0, 'M'},
        { "zoom",               required_argument, 0, 'm'},
        { "no-gridfit",         no_argument,       0, 'N'},
        { "font",               required_argument, 0, 'n'},
        { "logarithmic",        no_argument,       0, 'o'},
        { "pango-markup",       no_argument,       0, 'P'},
        { "font-render-mode",   required_argument, 0, 'R'},
        { "rigid",              no_argument,       0, 'r'},
        { "step",               required_argument, 0, 'S'},
        { "start",              required_argument, 0, 's'},
        { "tabwidth",           required_argument, 0, 'T'},
        { "title",              required_argument, 0, 't'},
        { "upper-limit",        required_argument, 0, 'u'},
        { "vertical-label",     required_argument, 0, 'v'},
        { "watermark",          required_argument, 0, 'W'},
        { "width",              required_argument, 0, 'w'},
        { "units-exponent",     required_argument, 0, 'X'},
        { "x-grid",             required_argument, 0, 'x'},
        { "alt-y-grid",         no_argument,       0, 'Y'},
        { "y-grid",             required_argument, 0, 'y'},
        { "lazy",               no_argument,       0, 'z'},
        { "use-nan-for-all-missing-data", no_argument,       0, 'Z'},
        { "units",              required_argument, 0, LONGOPT_UNITS_SI},
        { "alt-y-mrtg",         no_argument,       0, 1000},    /* this has no effect it is just here to save old apps from crashing when they use it */
        { "disable-rrdtool-tag",no_argument,       0, 1001},
        { "right-axis",         required_argument, 0, 1002},
        { "right-axis-label",   required_argument, 0, 1003},
        { "right-axis-format",  required_argument, 0, 1004},
        { "legend-position",    required_argument, 0, 1005},
        { "legend-direction",   required_argument, 0, 1006},
        { "border",             required_argument, 0, 1007},
        { "grid-dash",          required_argument, 0, 1008},
        { "dynamic-labels",     no_argument,       0, 1009},
        { "week-fmt",           required_argument, 0, 1010},
        { "graph-type",         required_argument, 0, 1011},
        { "left-axis-format",   required_argument, 0, 1012},
        {  0, 0, 0, 0}
};
/* *INDENT-ON* */

    optind = 0;
    opterr = 0;         /* initialize getopt */
    rrd_parsetime("end-24h", &start_tv);
    rrd_parsetime("now", &end_tv);
    while (1) {
        int       option_index = 0;
        int       opt;
        int       col_start, col_end;

        opt = getopt_long(argc, argv,
                          "Aa:B:b:c:Dd:Ee:Ff:G:gh:IiJjL:l:Mm:Nn:oPR:rS:s:T:t:u:v:W:w:X:x:Yy:Zz",
                          long_options, &option_index);
        if (opt == EOF)
            break;
        switch (opt) {
        case 'I':
            im->extra_flags |= NOMINOR;
            break;
        case 'Y':
            im->extra_flags |= ALTYGRID;
            break;
        case 'A':
            im->extra_flags |= ALTAUTOSCALE;
            break;
        case 'J':
            im->extra_flags |= ALTAUTOSCALE_MIN;
            break;
        case 'M':
            im->extra_flags |= ALTAUTOSCALE_MAX;
            break;
        case 'j':
            im->extra_flags |= ONLY_GRAPH;
            break;
        case 'g':
            im->extra_flags |= NOLEGEND;
            break;
        case 'Z':
            im->extra_flags |= ALLOW_MISSING_DS;
            break;
        case 1005:
            if (strcmp(optarg, "north") == 0) {
                im->legendposition = NORTH;
            } else if (strcmp(optarg, "west") == 0) {
                im->legendposition = WEST;
            } else if (strcmp(optarg, "south") == 0) {
                im->legendposition = SOUTH;
            } else if (strcmp(optarg, "east") == 0) {
                im->legendposition = EAST;
            } else {
                rrd_set_error("unknown legend-position '%s'", optarg);
                return;
            }
            break;
        case 1006:
            if (strcmp(optarg, "topdown") == 0) {
                im->legenddirection = TOP_DOWN;
            } else if (strcmp(optarg, "bottomup") == 0) {
                im->legenddirection = BOTTOM_UP;
            } else if (strcmp(optarg, "bottomup2") == 0) {
                im->legenddirection = BOTTOM_UP2;
            } else {
                rrd_set_error("unknown legend-position '%s'", optarg);
                return;
            }
            break;
        case 'F':
            im->extra_flags |= FORCE_RULES_LEGEND;
            break;
        case 1001:
            im->extra_flags |= NO_RRDTOOL_TAG;
            break;
        case LONGOPT_UNITS_SI:
            if (im->extra_flags & FORCE_UNITS) {
                rrd_set_error("--units can only be used once!");
                return;
            }
            if (strcmp(optarg, "si") == 0)
                im->extra_flags |= FORCE_UNITS_SI;
            else {
                rrd_set_error("invalid argument for --units: %s", optarg);
                return;
            }
            break;
        case 'X':
            im->unitsexponent = atoi(optarg);
            break;
        case 'L':
            im->unitslength = atoi(optarg);
            im->forceleftspace = 1;
            break;
        case 'T':
            if (rrd_strtodbl(optarg, 0, &(im->tabwidth), "option -T") != 2)
                return;
            break;
        case 'S':
            im->step = atoi(optarg);
            break;
        case 'N':
            im->gridfit = 0;
            break;
        case 'P':
            im->with_markup = 1;
            break;
        case 's':
            if ((parsetime_error = rrd_parsetime(optarg, &start_tv))) {
                rrd_set_error("start time: %s", parsetime_error);
                return;
            }
            break;
        case 'e':
            if ((parsetime_error = rrd_parsetime(optarg, &end_tv))) {
                rrd_set_error("end time: %s", parsetime_error);
                return;
            }
            break;
        case 'x':
            if (strcmp(optarg, "none") == 0) {
                im->draw_x_grid = 0;
                break;
            };
            if (sscanf(optarg,
                       "%10[A-Z]:%ld:%10[A-Z]:%ld:%10[A-Z]:%ld:%ld:%n",
                       scan_gtm,
                       &im->xlab_user.gridst,
                       scan_mtm,
                       &im->xlab_user.mgridst,
                       scan_ltm,
                       &im->xlab_user.labst,
                       &im->xlab_user.precis, &stroff) == 7 && stroff != 0) {
				im->xlab_form=strdup(optarg + stroff);
				if (!im->xlab_form) {
                    rrd_set_error("cannot allocate memory for xlab_form");
                    return;
				}
                if ((int)
                    (im->xlab_user.gridtm = tmt_conv(scan_gtm)) == -1) {
                    rrd_set_error("unknown keyword %s", scan_gtm);
                    return;
                } else if ((int)
                           (im->xlab_user.mgridtm = tmt_conv(scan_mtm))
                           == -1) {
                    rrd_set_error("unknown keyword %s", scan_mtm);
                    return;
                } else if ((int)
                           (im->xlab_user.labtm = tmt_conv(scan_ltm)) == -1) {
                    rrd_set_error("unknown keyword %s", scan_ltm);
                    return;
                }
                im->xlab_user.minsec = 1;
                im->xlab_user.stst = im->xlab_form ? im->xlab_form : "";
            } else {
                rrd_set_error("invalid x-grid format");
                return;
            }
            break;
        case 'y':
            if (strcmp(optarg, "none") == 0) {
                im->draw_y_grid = 0;
                break;
            };
            if (sscanf(optarg, "%[-0-9.e+]:%d", double_str , &im->ylabfact) == 2) {
                if (rrd_strtodbl( double_str, 0, &(im->ygridstep), "option -y") != 2){
                    return;
                }
                if (im->ygridstep <= 0) {
                    rrd_set_error("grid step must be > 0");
                    return;
                } else if (im->ylabfact < 1) {
                    rrd_set_error("label factor must be > 0");
                    return;
                }
            } else {
                rrd_set_error("invalid y-grid format");
                return;
            }
            break;
        case 1007:
            im->draw_3d_border = atoi(optarg);
            break;
        case 1008: /* grid-dash */
            if(sscanf(optarg,
                      "%[-0-9.e+]:%[-0-9.e+]",
                      double_str,
                      double_str2 ) != 2) {
                if ( rrd_strtodbl( double_str, 0, &(im->grid_dash_on),NULL) !=2 
                     || rrd_strtodbl( double_str2, 0, &(im->grid_dash_off), NULL) != 2 ){
                    rrd_set_error("expected grid-dash format float:float");
                    return;
                }
            }
            break;   
        case 1009: /* enable dynamic labels */
            im->dynamic_labels = 1;
            break;         
        case 1010:
            strncpy(week_fmt,optarg,sizeof week_fmt);
            week_fmt[(sizeof week_fmt)-1]='\0';
            break;
        case 1002: /* right y axis */
            if(sscanf(optarg,
                      "%[-0-9.e+]:%[-0-9.e+]",
                      double_str,
                      double_str2 ) == 2
                && rrd_strtodbl( double_str, 0, &(im->second_axis_scale),NULL) == 2
                && rrd_strtodbl( double_str2, 0, &(im->second_axis_shift),NULL) == 2){
                if(im->second_axis_scale==0){
                    rrd_set_error("the second_axis_scale  must not be 0");
                    return;
                }
            } else {
                rrd_set_error("invalid right-axis format expected scale:shift");
                return;
            }
            break;
        case 1003:
            im->second_axis_legend=strdup(optarg);
            if (!im->second_axis_legend) {
                rrd_set_error("cannot allocate memory for second_axis_legend");
                return;
            }
            break;
        case 1004:
            if (bad_format_axis(optarg)){
                return;
            }
            im->second_axis_format=strdup(optarg);
            if (!im->second_axis_format) {
                rrd_set_error("cannot allocate memory for second_axis_format");
                return;
            }
            break;
        case 1012:
            if (bad_format_axis(optarg)){
                return;
            }
            im->primary_axis_format=strdup(optarg);
            if (!im->primary_axis_format) {
                rrd_set_error("cannot allocate memory for primary_axis_format");
                return;
            }
            break;
        case 'v':
            im->ylegend=strdup(optarg);
            if (!im->ylegend) {
                rrd_set_error("cannot allocate memory for ylegend");
                return;
            }
            break;
        case 'u':
            if (rrd_strtodbl(optarg, 0, &(im->maxval), "option -u") != 2){
                return;
            }
            break;
        case 'l':
            if (rrd_strtodbl(optarg, 0, &(im->minval), "option -l") != 2){
                return;
            }
            break;
        case 'b':
            im->base = atol(optarg);
            if (im->base != 1024 && im->base != 1000) {
                rrd_set_error
                    ("the only sensible value for base apart from 1000 is 1024");
                return;
            }
            break;
        case 'w':
            long_tmp = atol(optarg);
            if (long_tmp < 10) {
                rrd_set_error("width below 10 pixels");
                return;
            }
            im->xsize = long_tmp;
            break;
        case 'h':
            long_tmp = atol(optarg);
            if (long_tmp < 10) {
                rrd_set_error("height below 10 pixels");
                return;
            }
            im->ysize = long_tmp;
            break;
        case 'D':
            im->extra_flags |= FULL_SIZE_MODE;
            break;
        case 'i':
            /* interlaced png not supported at the moment */
            break;
        case 'r':
            im->rigid = 1;
            break;
        case 'f':
            im->imginfo = optarg;
            break;
        case 'a':
            if ((int)
                (im->imgformat = if_conv(optarg)) == -1) {
                rrd_set_error("unsupported graphics format '%s'", optarg);
                return;
            }
            break;
        case 1011:
            if ((int)
                (im->graph_type = type_conv(optarg)) == -1) {
                rrd_set_error("unsupported graphics type '%s'", optarg);
                return;
            }
            break;
        case 'z':
            im->lazy = 1;
            break;
        case 'E':
            im->slopemode = 1;
            break;
        case 'o':
            im->logarithmic = 1;
            break;
        case 'c':
            if (sscanf(optarg,
                       "%10[A-Z]#%n%8lx%n",
                       col_nam, &col_start, &color, &col_end) == 2) {
                int       ci;
                int       col_len = col_end - col_start;

                switch (col_len) {
                case 3:
                    color =
                        (((color & 0xF00) * 0x110000) | ((color & 0x0F0) *
                                                         0x011000) |
                         ((color & 0x00F)
                          * 0x001100)
                         | 0x000000FF);
                    break;
                case 4:
                    color =
                        (((color & 0xF000) *
                          0x11000) | ((color & 0x0F00) *
                                      0x01100) | ((color &
                                                   0x00F0) *
                                                  0x00110) |
                         ((color & 0x000F) * 0x00011)
                        );
                    break;
                case 6:
                    color = (color << 8) + 0xff /* shift left by 8 */ ;
                    break;
                case 8:
                    break;
                default:
                    rrd_set_error("the color format is #RRGGBB[AA]");
                    return;
                }
                if ((ci = grc_conv(col_nam)) != -1) {
                    im->graph_col[ci] = gfx_hex_to_col(color);
                } else {
                    rrd_set_error("invalid color name '%s'", col_nam);
                    return;
                }
            } else {
                rrd_set_error("invalid color def format");
                return;
            }
            break;
        case 'n':{
            char      prop[15];
            double    size = 1;
            int       end;

            if (sscanf(optarg, "%10[A-Z]:%[-0-9.e+]%n", prop, double_str, &end) >= 2
                && rrd_strtodbl( double_str, 0, &size, NULL) == 2) {
                int       sindex, propidx;

                if ((sindex = text_prop_conv(prop)) != -1) {
                    for (propidx = sindex;
                         propidx < TEXT_PROP_LAST; propidx++) {
                        if (size > 0) {
                            rrd_set_font_desc(im,propidx,NULL,size);
                        }
                        if ((int) strlen(optarg) > end+2) {
                            if (optarg[end] == ':') {
                                rrd_set_font_desc(im,propidx,optarg + end + 1,0);
                            } else {
                                rrd_set_error
                                    ("expected : after font size in '%s'",
                                     optarg);
                                return;
                            }
                        }
                        /* only run the for loop for DEFAULT (0) for
                           all others, we break here. woodo programming */
                        if (propidx == sindex && sindex != 0)
                            break;
                    }
                } else {
                    rrd_set_error("invalid fonttag '%s'", prop);
                    return;
                }
            } else {
                rrd_set_error("invalid text property format");
                return;
            }
            break;
        }
        case 'm':
            if (rrd_strtodbl(optarg, 0, &(im->zoom), "option -m") != 2){
                return;
            }
            if (im->zoom <= 0.0) {
                rrd_set_error("zoom factor must be > 0");
                return;
            }
            break;
        case 't':
            im->title=strdup(optarg);
            if (!im->title) {
                rrd_set_error("cannot allocate memory for title");
                return;
            }
            break;
        case 'R':
            if (strcmp(optarg, "normal") == 0) {
                cairo_font_options_set_antialias
                    (im->font_options, CAIRO_ANTIALIAS_GRAY);
                cairo_font_options_set_hint_style
                    (im->font_options, CAIRO_HINT_STYLE_FULL);
            } else if (strcmp(optarg, "light") == 0) {
                cairo_font_options_set_antialias
                    (im->font_options, CAIRO_ANTIALIAS_GRAY);
                cairo_font_options_set_hint_style
                    (im->font_options, CAIRO_HINT_STYLE_SLIGHT);
            } else if (strcmp(optarg, "mono") == 0) {
                cairo_font_options_set_antialias
                    (im->font_options, CAIRO_ANTIALIAS_NONE);
                cairo_font_options_set_hint_style
                    (im->font_options, CAIRO_HINT_STYLE_FULL);
            } else {
                rrd_set_error("unknown font-render-mode '%s'", optarg);
                return;
            }
            break;
        case 'G':
            if (strcmp(optarg, "normal") == 0)
                im->graph_antialias = CAIRO_ANTIALIAS_GRAY;
            else if (strcmp(optarg, "mono") == 0)
                im->graph_antialias = CAIRO_ANTIALIAS_NONE;
            else {
                rrd_set_error("unknown graph-render-mode '%s'", optarg);
                return;
            }
            break;
        case 'B':
            /* not supported curently */
            break;
        case 'W':
            im->watermark=strdup(optarg);
            if (!im->watermark) {
                rrd_set_error("cannot allocate memory for watermark");
                return;
            }
            break;
        case 'd':
        {
            if (im->daemon_addr != NULL)
            {
                rrd_set_error ("You cannot specify --daemon "
                        "more than once.");
                return;
            }

            im->daemon_addr = strdup(optarg);
            if (im->daemon_addr == NULL)
            {
              rrd_set_error("strdup failed");
              return;
            }

            break;
        }
        case '?':
            if (optopt != 0)
                rrd_set_error("unknown option '%c'", optopt);
            else
                rrd_set_error("unknown option '%s'", argv[optind - 1]);
            return;
        }
    } /* while (1) */

    pango_cairo_context_set_font_options(pango_layout_get_context(im->layout), im->font_options);
    pango_layout_context_changed(im->layout);



    if (im->logarithmic && im->minval <= 0) {
        rrd_set_error
            ("for a logarithmic yaxis you must specify a lower-limit > 0");
        return;
    }

    if (rrd_proc_start_end(&start_tv, &end_tv, &start_tmp, &end_tmp) == -1) {
        /* error string is set in rrd_parsetime.c */
        return;
    }

    if (start_tmp < 3600 * 24 * 365 * 10) {
        rrd_set_error
            ("the first entry to fetch should be after 1980 (%ld)",
             start_tmp);
        return;
    }

    if (end_tmp < start_tmp) {
        rrd_set_error
            ("start (%ld) should be less than end (%ld)", start_tmp, end_tmp);
        return;
    }

    im->start = start_tmp;
    im->end = end_tmp;
    im->step = max((long) im->step, (im->end - im->start) / im->xsize);
}

int print_calc(
    image_desc_t *im)
{
    long      i, ii, validsteps;
    double    printval;
    struct tm tmvdef;
    int       graphelement = 0;
    long      vidx;
    int       max_ii;
    double    magfact = -1;
    char     *si_symb = "";
    char     *percent_s;
    int       prline_cnt = 0;

    /* wow initializing tmvdef is quite a task :-) */
    time_t    now = time(NULL);

    localtime_r(&now, &tmvdef);
    for (i = 0; i < im->gdes_c; i++) {
        vidx = im->gdes[i].vidx;
        switch (im->gdes[i].gf) {
        case GF_PRINT:
        case GF_GPRINT:
            /* PRINT and GPRINT can now print VDEF generated values.
             * There's no need to do any calculations on them as these
             * calculations were already made.
             */
            if (im->gdes[vidx].gf == GF_VDEF) { /* simply use vals */
                printval = im->gdes[vidx].vf.val;
                localtime_r(&im->gdes[vidx].vf.when, &tmvdef);
            } else {    /* need to calculate max,min,avg etcetera */
                max_ii = ((im->gdes[vidx].end - im->gdes[vidx].start)
                          / im->gdes[vidx].step * im->gdes[vidx].ds_cnt);
                printval = DNAN;
                validsteps = 0;
                for (ii = im->gdes[vidx].ds;
                     ii < max_ii; ii += im->gdes[vidx].ds_cnt) {
                    if (!finite(im->gdes[vidx].data[ii]))
                        continue;
                    if (isnan(printval)) {
                        printval = im->gdes[vidx].data[ii];
                        validsteps++;
                        continue;
                    }

                    switch (im->gdes[i].cf) {
                    case CF_HWPREDICT:
                    case CF_MHWPREDICT:
                    case CF_DEVPREDICT:
                    case CF_DEVSEASONAL:
                    case CF_SEASONAL:
                    case CF_AVERAGE:
                        validsteps++;
                        printval += im->gdes[vidx].data[ii];
                        break;
                    case CF_MINIMUM:
                        printval = min(printval, im->gdes[vidx].data[ii]);
                        break;
                    case CF_FAILURES:
                    case CF_MAXIMUM:
                        printval = max(printval, im->gdes[vidx].data[ii]);
                        break;
                    case CF_LAST:
                        printval = im->gdes[vidx].data[ii];
                    }
                }
                if (im->gdes[i].cf == CF_AVERAGE || im->gdes[i].cf > CF_LAST) {
                    if (validsteps > 1) {
                        printval = (printval / validsteps);
                    }
                }
            }           /* prepare printval */

            if (!im->gdes[i].strftm && (percent_s = strstr(im->gdes[i].format, "%S")) != NULL) {
                /* Magfact is set to -1 upon entry to print_calc.  If it
                 * is still less than 0, then we need to run auto_scale.
                 * Otherwise, put the value into the correct units.  If
                 * the value is 0, then do not set the symbol or magnification
                 * so next the calculation will be performed again. */
                if (magfact < 0.0) {
                    auto_scale(im, &printval, &si_symb, &magfact);
                    if (printval == 0.0)
                        magfact = -1.0;
                } else {
                    printval /= magfact;
                }
                *(++percent_s) = 's';
            } else if (!im->gdes[i].strftm && strstr(im->gdes[i].format, "%s") != NULL) {
                auto_scale(im, &printval, &si_symb, &magfact);
            }

            if (im->gdes[i].gf == GF_PRINT) {
                rrd_infoval_t prline;

                if (im->gdes[i].strftm) {
                    prline.u_str = (char*)malloc((FMT_LEG_LEN + 2) * sizeof(char));
                    if (im->gdes[vidx].vf.never == 1) {
                       time_clean(prline.u_str, im->gdes[i].format);
                    } else {
                        strftime(prline.u_str,
                                 FMT_LEG_LEN, im->gdes[i].format, &tmvdef);
                    }
                } else if (bad_format_print(im->gdes[i].format)) {
                    return -1;
                } else {
                    prline.u_str =
                        sprintf_alloc(im->gdes[i].format, printval, si_symb);
                }
                grinfo_push(im,
                            sprintf_alloc
                            ("print[%ld]", prline_cnt++), RD_I_STR, prline);
                free(prline.u_str);
            } else {
                /* GF_GPRINT */

                if (im->gdes[i].strftm) {
                    if (im->gdes[vidx].vf.never == 1) {
                       time_clean(im->gdes[i].legend, im->gdes[i].format);
                    } else {
                        strftime(im->gdes[i].legend,
                                 FMT_LEG_LEN, im->gdes[i].format, &tmvdef);
                    }
                } else {
                    if (bad_format_print(im->gdes[i].format)) {
                       return -1;
                    }
                    snprintf(im->gdes[i].legend,
                             FMT_LEG_LEN - 2,
                             im->gdes[i].format, printval, si_symb);
                }
                graphelement = 1;
            }
            break;
        case GF_LINE:
        case GF_AREA:
		case GF_GRAD:
        case GF_TICK:
            graphelement = 1;
            break;
        case GF_HRULE:
            if (isnan(im->gdes[i].yrule)) { /* we must set this here or the legend printer can not decide to print the legend */
                im->gdes[i].yrule = im->gdes[vidx].vf.val;
            };
            graphelement = 1;
            break;
        case GF_VRULE:
            if (im->gdes[i].xrule == 0) {   /* again ... the legend printer needs it */
                im->gdes[i].xrule = im->gdes[vidx].vf.when;
            };
            graphelement = 1;
            break;
        case GF_COMMENT:
        case GF_TEXTALIGN:
        case GF_DEF:
        case GF_CDEF:
        case GF_VDEF:
#ifdef WITH_PIECHART
        case GF_PART:
#endif
        case GF_SHIFT:
        case GF_XPORT:
            break;
        case GF_STACK:
            rrd_set_error
                ("STACK should already be turned into LINE or AREA here");
            return -1;
            break;
        case GF_XAXIS:
        case GF_YAXIS:
	    break;
        }
    }
    return graphelement;
}

std::string bdecode_error_category::message(int ev) const BOOST_SYSTEM_NOEXCEPT
{
	static char const* msgs[] =
	{
		"no error",
		"expected string in bencoded string",
		"expected colon in bencoded string",
		"unexpected end of file in bencoded string",
		"expected value (list, dict, int or string) in bencoded string",
		"bencoded nesting depth exceeded",
		"bencoded item count limit exceeded",
		"integer overflow",
	};
	if (ev < 0 || ev >= int(sizeof(msgs)/sizeof(msgs[0])))
		return "Unknown error";
	return msgs[ev];
}

boost::system::error_code make_error_code(error_code_enum e)
{
	return boost::system::error_code(e, get_bdecode_category());
}

int fail(int* error_pos
	, std::vector<lazy_entry*>& stack
	, char const* start
	, char const* orig_start)
{
	while (!stack.empty()) {
		lazy_entry* top = stack.back();
		if (top->type() == lazy_entry::dict_t || top->type() == lazy_entry::list_t)
		{
			top->pop();
			break;
		}
		stack.pop_back();
	}
	if (error_pos) *error_pos = start - orig_start;
	return -1;
}

int lazy_bdecode(char const* start, char const* end, lazy_entry& ret
	, error_code& ec, int* error_pos, int depth_limit, int item_limit)
{
	char const* const orig_start = start;
	ret.clear();
	if (start == end) return 0;

	std::vector<lazy_entry*> stack;

	stack.push_back(&ret);
	while (start <= end)
	{
		if (stack.empty()) break; // done!

		lazy_entry* top = stack.back();

		if (int(stack.size()) > depth_limit) TORRENT_FAIL_BDECODE(bdecode_errors::depth_exceeded);
		if (start >= end) TORRENT_FAIL_BDECODE(bdecode_errors::unexpected_eof);
		char t = *start;
		++start;
		if (start >= end && t != 'e') TORRENT_FAIL_BDECODE(bdecode_errors::unexpected_eof);

		switch (top->type())
		{
			case lazy_entry::dict_t:
			{
				if (t == 'e')
				{
					top->set_end(start);
					stack.pop_back();
					continue;
				}
				if (!numeric(t)) TORRENT_FAIL_BDECODE(bdecode_errors::expected_string);
				boost::int64_t len = t - '0';
				bdecode_errors::error_code_enum e = bdecode_errors::no_error;
				start = parse_int(start, end, ':', len, e);
				if (e)
					TORRENT_FAIL_BDECODE(e);

				if (start + len + 1 > end)
					TORRENT_FAIL_BDECODE(bdecode_errors::unexpected_eof);

				if (len < 0)
					TORRENT_FAIL_BDECODE(bdecode_errors::overflow);

				++start;
				if (start == end) TORRENT_FAIL_BDECODE(bdecode_errors::unexpected_eof);
				lazy_entry* ent = top->dict_append(start);
				if (ent == 0) TORRENT_FAIL_BDECODE(boost::system::errc::not_enough_memory);
				start += len;
				if (start >= end) TORRENT_FAIL_BDECODE(bdecode_errors::unexpected_eof);
				stack.push_back(ent);
				t = *start;
				++start;
				break;
			}
			case lazy_entry::list_t:
			{
				if (t == 'e')
				{
					top->set_end(start);
					stack.pop_back();
					continue;
				}
				lazy_entry* ent = top->list_append();
				if (ent == 0) TORRENT_FAIL_BDECODE(boost::system::errc::not_enough_memory);
				stack.push_back(ent);
				break;
			}
			default: break;
		}

		--item_limit;
		if (item_limit <= 0) TORRENT_FAIL_BDECODE(bdecode_errors::limit_exceeded);

		top = stack.back();
		switch (t)
		{
			case 'd':
				top->construct_dict(start - 1);
				continue;
			case 'l':
				top->construct_list(start - 1);
				continue;
			case 'i':
			{
				char const* int_start = start;
				start = find_char(start, end, 'e');
				top->construct_int(int_start, start - int_start);
				if (start == end) TORRENT_FAIL_BDECODE(bdecode_errors::unexpected_eof);
				TORRENT_ASSERT(*start == 'e');
				++start;
				stack.pop_back();
				continue;
			}
			default:
			{
				if (!numeric(t))
					TORRENT_FAIL_BDECODE(bdecode_errors::expected_value);

				boost::int64_t len = t - '0';
				bdecode_errors::error_code_enum e = bdecode_errors::no_error;
				start = parse_int(start, end, ':', len, e);
				if (e)
					TORRENT_FAIL_BDECODE(e);
				if (start + len + 1 > end)
					TORRENT_FAIL_BDECODE(bdecode_errors::unexpected_eof);
				if (len < 0)
					TORRENT_FAIL_BDECODE(bdecode_errors::overflow);

				++start;
				top->construct_string(start, int(len));
				stack.pop_back();
				start += len;
				continue;
			}
		}
		return 0;
	}
	return 0;
}

lazy_entry* lazy_entry::dict_find(std::string const& name)
{
	TORRENT_ASSERT(m_type == dict_t);
	for (int i = 0; i < int(m_size); ++i)
	{
		lazy_dict_entry& e = m_data.dict[i];
		if (name.size() != e.val.m_begin - e.name) continue;
		if (std::equal(name.begin(), name.end(), e.name))
			return &e.val;
	}
	return 0;
}

lazy_entry const* lazy_entry::dict_find_dict(std::string const& name) const
{
	lazy_entry const* e = dict_find(name);
	if (e == 0 || e->type() != lazy_entry::dict_t) return 0;
	return e;
}

boost::int64_t lazy_entry::int_value() const
{
	TORRENT_ASSERT(m_type == int_t);
	boost::int64_t val = 0;
	bool negative = false;
	if (*m_data.start == '-') negative = true;
	bdecode_errors::error_code_enum ec = bdecode_errors::no_error;
	parse_int(m_data.start + negative
		, m_data.start + m_size, 'e', val, ec);
	if (ec) return 0;
	if (negative) val = -val;
	return val;
}

char const* parse_int(char const* start, char const* end, char delimiter
	, boost::int64_t& val, bdecode_errors::error_code_enum& ec)
{
	while (start < end && *start != delimiter)
	{
		if (!numeric(*start))
		{
			ec = bdecode_errors::expected_string;
			return start;
		}
		if (val > INT64_MAX / 10)
		{
			ec = bdecode_errors::overflow;
			return start;
		}
		val *= 10;
		int digit = *start - '0';
		if (val > INT64_MAX - digit)
		{
			ec = bdecode_errors::overflow;
			return start;
		}
		val += digit;
		++start;
	}
	if (*start != delimiter)
		ec = bdecode_errors::expected_colon;
	return start;
}

std::string print_entry(lazy_entry const& e, bool single_line, int indent)
{
	char indent_str[200];
	memset(indent_str, ' ', 200);
	indent_str[0] = ',';
	indent_str[1] = '\n';
	indent_str[199] = 0;
	if (indent < 197 && indent >= 0) indent_str[indent+2] = 0;
	std::string ret;
	switch (e.type())
	{
		case lazy_entry::none_t: return "none";
		case lazy_entry::int_t:
		{
			char str[100];
			snprintf(str, sizeof(str), "%" PRId64, e.int_value());
			return str;
		}
		case lazy_entry::string_t:
		{
			bool printable = true;
			char const* str = e.string_ptr();
			for (int i = 0; i < e.string_length(); ++i)
			{
				char c = str[i];
				if (c >= 32 && c < 127) continue;
				printable = false;
				break;
			}
			ret += "'";
			if (printable)
			{
				if (single_line && e.string_length() > 30)
				{
					ret.append(e.string_ptr(), 14);
					ret += "...";
					ret.append(e.string_ptr() + e.string_length()-14, 14);
				}
				else
					ret.append(e.string_ptr(), e.string_length());
				ret += "'";
				return ret;
			}
			if (single_line && e.string_length() > 20)
			{
				for (int i = 0; i < 9; ++i)
				{
					char tmp[5];
					snprintf(tmp, sizeof(tmp), "%02x", (unsigned char)str[i]);
					ret += tmp;
				}
				ret += "...";
				for (int i = e.string_length() - 9
					, len(e.string_length()); i < len; ++i)
				{
					char tmp[5];
					snprintf(tmp, sizeof(tmp), "%02x", (unsigned char)str[i]);
					ret += tmp;
				}
			}
			else
			{
				for (int i = 0; i < e.string_length(); ++i)
				{
					char tmp[5];
					snprintf(tmp, sizeof(tmp), "%02x", (unsigned char)str[i]);
					ret += tmp;
				}
			}
			ret += "'";
			return ret;
		}
		case lazy_entry::list_t:
		{
			ret += '[';
			bool one_liner = line_longer_than(e, 200) != -1 || single_line;

			if (!one_liner) ret += indent_str + 1;
			for (int i = 0; i < e.list_size(); ++i)
			{
				if (i == 0 && one_liner) ret += " ";
				ret += print_entry(*e.list_at(i), single_line, indent + 2);
				if (i < e.list_size() - 1) ret += (one_liner?", ":indent_str);
				else ret += (one_liner?" ":indent_str+1);
			}
			ret += "]";
			return ret;
		}
		case lazy_entry::dict_t:
		{
			ret += "{";
			bool one_liner = line_longer_than(e, 200) != -1 || single_line;

			if (!one_liner) ret += indent_str+1;
			for (int i = 0; i < e.dict_size(); ++i)
			{
				if (i == 0 && one_liner) ret += " ";
				std::pair<std::string, lazy_entry const*> ent = e.dict_at(i);
				ret += "'";
				ret += ent.first;
				ret += "': ";
				ret += print_entry(*ent.second, single_line, indent + 2);
				if (i < e.dict_size() - 1) ret += (one_liner?", ":indent_str);
				else ret += (one_liner?" ":indent_str+1);
			}
			ret += "}";
			return ret;
		}
	}
	return ret;
}

int lazy_bdecode(char const* start, char const* end, lazy_entry& ret
	, error_code& ec, int* error_pos, int depth_limit, int item_limit)
{
	char const* const orig_start = start;
	ret.clear();
	if (start == end) return 0;

	std::vector<lazy_entry*> stack;

	stack.push_back(&ret);
	while (start < end)
	{
		if (stack.empty()) break; // done!

		lazy_entry* top = stack.back();

		if (int(stack.size()) > depth_limit) TORRENT_FAIL_BDECODE(bdecode_errors::depth_exceeded);
		if (start >= end) TORRENT_FAIL_BDECODE(bdecode_errors::unexpected_eof);
		char t = *start;
		++start;
		if (start >= end && t != 'e') TORRENT_FAIL_BDECODE(bdecode_errors::unexpected_eof);

		switch (top->type())
		{
			case lazy_entry::dict_t:
			{
				if (t == 'e')
				{
					top->set_end(start);
					stack.pop_back();
					continue;
				}
				if (!is_digit(t)) TORRENT_FAIL_BDECODE(bdecode_errors::expected_string);
				boost::int64_t len = t - '0';
				start = parse_int(start, end, ':', len);
				if (start == 0 || start + len + 3 > end || *start != ':')
					TORRENT_FAIL_BDECODE(bdecode_errors::expected_colon);
				++start;
				if (start == end) TORRENT_FAIL_BDECODE(bdecode_errors::unexpected_eof);
				lazy_entry* ent = top->dict_append(start);
				if (ent == 0) TORRENT_FAIL_BDECODE(boost::system::errc::not_enough_memory);
				start += len;
				if (start >= end) TORRENT_FAIL_BDECODE(bdecode_errors::unexpected_eof);
				stack.push_back(ent);
				t = *start;
				++start;
				break;
			}
			case lazy_entry::list_t:
			{
				if (t == 'e')
				{
					top->set_end(start);
					stack.pop_back();
					continue;
				}
				lazy_entry* ent = top->list_append();
				if (ent == 0) TORRENT_FAIL_BDECODE(boost::system::errc::not_enough_memory);
				stack.push_back(ent);
				break;
			}
			default: break;
		}

		--item_limit;
		if (item_limit <= 0) TORRENT_FAIL_BDECODE(bdecode_errors::limit_exceeded);

		top = stack.back();
		switch (t)
		{
			case 'd':
				top->construct_dict(start - 1);
				continue;
			case 'l':
				top->construct_list(start - 1);
				continue;
			case 'i':
			{
				char const* int_start = start;
				start = find_char(start, end, 'e');
				top->construct_int(int_start, start - int_start);
				if (start == end) TORRENT_FAIL_BDECODE(bdecode_errors::unexpected_eof);
				TORRENT_ASSERT(*start == 'e');
				++start;
				stack.pop_back();
				continue;
			}
			default:
			{
				if (!is_digit(t))
					TORRENT_FAIL_BDECODE(bdecode_errors::expected_value);

				boost::int64_t len = t - '0';
				start = parse_int(start, end, ':', len);
				if (start == 0 || start + len + 1 > end || *start != ':')
					TORRENT_FAIL_BDECODE(bdecode_errors::expected_colon);
				++start;
				top->construct_string(start, int(len));
				stack.pop_back();
				start += len;
				continue;
			}
		}
		return 0;
	}
	return 0;
}

boost::int64_t lazy_entry::int_value() const
{
	TORRENT_ASSERT(m_type == int_t);
	boost::int64_t val = 0;
	bool negative = false;
	if (*m_data.start == '-') negative = true;
	parse_int(negative?m_data.start+1:m_data.start, m_data.start + m_size, 'e', val);
	if (negative) val = -val;
	return val;
}

char const* parse_int(char const* start, char const* end, char delimiter, boost::int64_t& val)
{
	while (start < end && *start != delimiter)
	{
		if (!is_digit(*start)) { return 0; }
		val *= 10;
		val += *start - '0';
		++start;
	}
	return start;
}

